SELECT ?investorName (SUM(CASE WHEN ?cashFlowType = "Withdrawal" THEN xsd:decimal(?amount) ELSE 0 END) AS ?totalWithdrawals)
       (SUM(CASE WHEN ?cashFlowType = "Deposit" THEN xsd:decimal(?amount) ELSE 0 END) AS ?totalDeposits)
       (CASE 
          WHEN SUM(CASE WHEN ?cashFlowType = "Deposit" THEN xsd:decimal(?amount) ELSE 0 END) > 0
          THEN SUM(CASE WHEN ?cashFlowType = "Withdrawal" THEN xsd:decimal(?amount) ELSE 0 END) / SUM(CASE WHEN ?cashFlowType = "Deposit" THEN xsd:decimal(?amount) ELSE 0 END)
          ELSE 0
        END AS ?withdrawalToDepositRatio)
WHERE {
  ?cashFlow a ex:CashFlow ;
            ex:hasInvestor ?investorProfile ;
            ex:amount ?amount ;
            ex:cashFlowType ?cashFlowType .

  ?investorProfile a ex:InvestorProfile ;
                    ex:investorName ?investorName .
}
GROUP BY ?investorName

