PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (COUNT(?rebalancingAction) AS ?count)
WHERE {
  ?rebalancingAction a ex:RebalancingAction ;
                     ex:logic "Underweight"^^xsd:string .
}

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?changeDirection (AVG(xsd:decimal(?newAllocationPct)) AS ?averageRevisedAllocation)
WHERE {
  ?scenarioRebalancing a ex:ScenarioRebalancing ;
                       ex:newAllocationPct ?newAllocationPct ;
                       ex:currentAllocationPct ?currentAllocationPct .

  BIND(IF(?newAllocationPct > ?currentAllocationPct, "Increased", "Decreased") AS ?changeDirection)
}
GROUP BY ?changeDirection

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (COUNT(?investor) AS ?totalCount)
WHERE {
  ?portfolioHealth ex:riskScore "At Risk" ;
                    ex:hasInvestor ?investor .
  ?investor a ex:InvestorProfile ;
            ex:notes "Interest Rate Hike scenario" .
}

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?sectorName (MAX(xsd:decimal(?totalInvestment)) AS ?maxTotalInvestment)
WHERE {
  ?allocation a ex:SectorAllocation ;
              ex:sectorName ?sectorName ;
              ex:totalInvestment ?totalInvestment .
}
GROUP BY ?sectorName
ORDER BY DESC(?maxTotalInvestment)
LIMIT 1

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorName
WHERE {
  ?investor a ex:InvestorProfile ;
            ex:investorName ?investorName .

  FILTER NOT EXISTS {
    ?holding a ex:PortfolioHolding ;
             ex:hasInvestor ?investor ;
             ex:purchaseDate ?purchaseDate .

    BIND(xsd:date(?purchaseDate) AS ?date)
    FILTER(?date >= xsd:date("2023-01-01"))
  }
}

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investor ?liquidityScore
WHERE {
  ?allocation a ex:SectorAllocation ;
              ex:sectorName "Technology" ;
              ex:allocationPct ?allocationPct ;
              ex:hasInvestor ?investor .

  FILTER(?allocationPct > 40)

  ?portfolioHealth a ex:PortfolioHealth ;
                   ex:hasInvestor ?investor ;
                   ex:liquidityScore ?liquidityScore .
}

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorName (SUM(xsd:decimal(?cost)) AS ?totalInvestment)
WHERE {
  ?investor a ex:InvestorProfile ;
            ex:investorName ?investorName .
  ?holding a ex:PortfolioHolding ;
           ex:hasInvestor ?investor ;
           ex:purchaseDate ?purchaseDate ;
           ex:cost ?cost .
  FILTER (YEAR(xsd:date(?purchaseDate)) = 2023)
}
GROUP BY ?investorName
ORDER BY DESC(?totalInvestment)
LIMIT 1

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (COUNT(?holding) AS ?count)
WHERE {
  ?holding a ex:PortfolioHolding ;
           ex:purchaseDate ?purchaseDate .
  FILTER (STRSTARTS(UCASE(?purchaseDate), "BEFORE 2022"))
}

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorName (SUM(xsd:decimal(?amount)) AS ?totalLumpSumInvestment)
WHERE {
  ?cashFlow a ex:CashFlow ;
            ex:cashFlowType "Lump Sum" ;
            ex:amount ?amount ;
            ex:hasInvestor ?investorProfile .
  ?investorProfile a ex:InvestorProfile ;
                    ex:investorName ?investorName .
}
GROUP BY ?investorName

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (COUNT(?holding) AS ?totalHoldings)
WHERE {
  ?holding a ex:PortfolioHolding ;
           ex:purchaseDate ?purchaseDate .
  FILTER (STRSTARTS(UCASE(?purchaseDate), "BEFORE 2022"))
}

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (COUNT(DISTINCT ?investor) AS ?totalInvestors)
WHERE {
  ?investor a ex:InvestorProfile ;
            ex:hasHolding ?holding .
  ?holding a ex:PortfolioHolding ;
           ex:investmentTypeLiteral "Gold"^^xsd:string .
}

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?categoryLiteral (AVG(xsd:decimal(?taxesPaid)) AS ?averageTaxes)
WHERE {
  ?portfolioHolding a ex:PortfolioHolding ;
                     ex:categoryLiteral ?categoryLiteral ;
                     ex:taxesPaid ?taxesPaid .
}
GROUP BY ?categoryLiteral
ORDER BY ASC(?averageTaxes)
LIMIT 1

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?categoryLiteral (AVG(xsd:decimal(?taxesPaid)) AS ?averageTaxesPaid)
WHERE {
  ?portfolioHolding a ex:PortfolioHolding ;
                     ex:categoryLiteral ?categoryLiteral ;
                     ex:taxesPaid ?taxesPaid .
}
GROUP BY ?categoryLiteral

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (COUNT(?holding) AS ?totalHoldings)
WHERE {
  ?investor a ex:InvestorProfile ;
            ex:riskTolerance "Conservative" .
  ?investor ex:hasHolding ?holding .
}

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT 
  (COUNT(?rebalancingAction) AS ?numberOfActions)
  (?sectorName AS ?Sector)
  ((SUM(xsd:decimal(?currentAllocationPct)) - SUM(xsd:decimal(?targetAllocationPct))) AS ?deviationFromTarget)

WHERE {
  ?rebalancingAction a ex:RebalancingAction ;
    ex:hasInvestor ?investor ;
    ex:currentAllocationPct ?currentAllocationPct ;
    ex:targetAllocationPct ?targetAllocationPct .

  ?sectorAllocation a ex:SectorAllocation ;
    ex:hasInvestor ?investor ;
    ex:allocationPct ?allocationPct ;
    ex:sectorName ?sectorName .
}

GROUP BY ?sectorName

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?sectorName (SUM(xsd:decimal(?totalInvestment)) AS ?totalAmount)
WHERE {
  ?allocation a ex:SectorAllocation ;
              ex:sectorName ?sectorName ;
              ex:totalInvestment ?totalInvestment .
}
GROUP BY ?sectorName
ORDER BY DESC(?totalAmount)
LIMIT 1

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (SUM(xsd:decimal(?amount)) AS ?totalDividendCashFlow)
WHERE {
  ?cashFlow a ex:CashFlow ;
            ex:hasInvestor ?investor ;
            ex:cashFlowType "dividend"^^xsd:string ;
            ex:amount ?amount .
  FILTER(CONTAINS(LCASE(STR(?investor)), "inv-049"))
}

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?categoryLiteral (SUM(xsd:decimal(?currentValue)) AS ?totalPortfolioValue)
WHERE {
  ?portfolioHolding a ex:PortfolioHolding ;
                     ex:categoryLiteral ?categoryLiteral ;
                     ex:currentValue ?currentValue .
}
GROUP BY ?categoryLiteral
ORDER BY ASC(?totalPortfolioValue)
LIMIT 1

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (SUM(xsd:decimal(?amount)) AS ?totalCashInflow)
WHERE {
  ?cashFlow a ex:CashFlow ;
            ex:cashFlowType "Deposit"^^xsd:string ;
            ex:date ?date ;
            ex:amount ?amount .
  FILTER(DATE(?date) >= DATE_SUB(CURRENT_DATE, INTERVAL 12 MONTH))
}
UNION
{
  SELECT (SUM(xsd:decimal(?amount)) AS ?totalCashInflow)
  WHERE {
    ?cashFlow a ex:CashFlow ;
              ex:cashFlowType "SIP Contribution"^^xsd:string ;
              ex:date ?date ;
              ex:amount ?amount .
    FILTER(DATE(?date) >= DATE_SUB(CURRENT_DATE, INTERVAL 12 MONTH))
  }
}

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (COUNT(?holding) AS ?totalCount)
WHERE {
  ?holding a ex:PortfolioHolding ;
           ex:purchaseDate ?purchaseDate .
  FILTER (STRSTARTS(UCASE(?purchaseDate), "BEFORE 2022"))
}

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorName (SUM(xsd:decimal(?taxesPaid)) AS ?totalTaxes)
WHERE {
  ?investor a ex:InvestorProfile ;
            ex:investorName ?investorName .
  ?holding a ex:PortfolioHolding ;
           ex:hasInvestor ?investor ;
           ex:taxesPaid ?taxesPaid .
}
GROUP BY ?investorName
ORDER BY DESC(?totalTaxes)
LIMIT 1

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (COUNT(?investor) AS ?totalCount)
WHERE {
  ?investor a ex:InvestorProfile ;
            ex:riskTolerance "Conservative" .

  ?portfolioHealth a ex:PortfolioHealth ;
                   ex:hasInvestor ?investor ;
                   ex:diversificationScore ?diversificationScore .

  FILTER (xsd:decimal(?diversificationScore) < 50)
}

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorName (AVG(xsd:decimal(?holdingDuration)) AS ?averageHoldingDuration)
WHERE {
  ?investor a ex:InvestorProfile ;
            ex:investorName ?investorName ;
            ex:hasHolding ?holding .

  ?holding a ex:PortfolioHolding ;
           ex:purchaseDate ?purchaseDate ;
           ex:currentValue ?currentValue .

  BIND(DATEDIFF(?purchaseDate, NOW()) AS ?holdingDuration)
}
GROUP BY ?investorName
ORDER BY DESC(?averageHoldingDuration)
LIMIT 1

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (SUM(xsd:decimal(?cost)) AS ?totalInvestmentCost)
WHERE {
  ?portfolioHolding a ex:PortfolioHolding ;
                     ex:purchaseDate ?purchaseDate ;
                     ex:cost ?cost .
  FILTER(CONTAINS(LCASE(STR(?purchaseDate)), "2022"))
}

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorName (SUM(xsd:decimal(?withdrawalAmount)) AS ?totalWithdrawals) (SUM(xsd:decimal(?depositAmount)) AS ?totalDeposits) 
       (IF(?totalDeposits = 0, "N/A", xsd:decimal(?totalWithdrawals) / xsd:decimal(?totalDeposits)) AS ?withdrawalToDepositRatio)
WHERE {
  ?cashFlow ex:hasInvestor ?investorProfile.
  ?investorProfile ex:investorName ?investorName.

  OPTIONAL {
    ?withdrawalCashFlow ex:hasInvestor ?investorProfile;
                        ex:cashFlowType "Withdrawal";
                        ex:amount ?withdrawalAmount.
  }

  OPTIONAL {
    ?depositCashFlow ex:hasInvestor ?investorProfile;
                      ex:cashFlowType "Deposit";
                      ex:amount ?depositAmount.
  }
}
GROUP BY ?investorName
